import {
  areaAnimation,
  isAreaCanvasEqual,
} from '../functions/animations/area-canvas.js';
import { printAreaBuilder } from '../functions/shapes/area-canvas.js';
import { useCanvas } from '../hooks/useCanvas.js';
import { useCanvasAnimation } from '../hooks/useCanvasAnimation.js';
import {
  AreaCanvasInstance,
  AreaCanvasProps,
  FnCanvasAccessor,
} from '../types/canvas-shape.js';

export function AreaCanvas<Datum>(props: AreaCanvasProps<Datum>) {
  const {
    radius,
    strokeWidth = 2,
    animation = { enabled: false },
    lineStrokeWidth = 2,
    ...propsAreaCanvas
  } = props;

  // Build how Line canvas should style
  const drawArea = printAreaBuilder<Datum>(
    strokeWidth,
    radius,
    lineStrokeWidth,
  );

  // Define draw method for entire Areas shape
  const drawAreaCanvas = (
    ctx: CanvasRenderingContext2D,
    canvas: AreaCanvasInstance<Datum>,
  ) => drawArea(ctx, canvas, canvas.x, canvas.y0, canvas.y1);

  // Define draw tick per animation lap for Areas shape
  const onTickAnimation = (
    progress: number,
    ctx: CanvasRenderingContext2D,
    areaCanvas: AreaCanvasInstance<Datum>,
    prevCanvas?: AreaCanvasInstance<Datum>,
  ) => {
    const areaTick = (
      x: FnCanvasAccessor<Datum>,
      y0: FnCanvasAccessor<Datum>,
      y1: FnCanvasAccessor<Datum>,
    ) => drawArea(ctx, areaCanvas, x, y0, y1);
    areaAnimation(areaCanvas, progress, areaTick, prevCanvas);
  };

  // Register shape/draw
  const isAreaCanvasDefinedEqual = (
    current: AreaCanvasInstance<Datum>,
    prev: AreaCanvasInstance<Datum>,
  ) =>
    isAreaCanvasEqual(
      {
        ...current,
        data: current.data.filter(
          current.defined ? current.defined : () => true,
        ),
      },
      //TODO: ADES-4720 make safeGate dont break in the previous data.
      {
        ...prev,
        data: prev.data.filter(prev.defined ? prev.defined : () => true),
      },
    );

  const { draw } = useCanvasAnimation<AreaCanvasInstance<Datum>, Datum>(
    propsAreaCanvas,
    drawAreaCanvas,
    animation.enabled ?? false,
    isAreaCanvasDefinedEqual,
    onTickAnimation,
    // TODO canvas animation improvements + enablement tackled in ADES-4720
    animation.duration,
  );

  useCanvas('area', draw);

  return null;
}
